import math


def _num(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("expected number")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError("number must be finite")
    return value


def _items(value, label):
    if isinstance(value, (str, bytes)):
        raise TypeError(label + " must be iterable")
    try:
        return list(value)
    except TypeError:
        raise TypeError(label + " must be iterable") from None


def simulate_zones(zones, links, targets, steps):
    if isinstance(steps, bool) or not isinstance(steps, int):
        raise TypeError("steps must be an integer")
    if steps < 0:
        raise ValueError("steps must be non-negative")
    data = []
    names = set()
    for zone in _items(zones, "zones"):
        if not isinstance(zone, dict):
            raise TypeError("zone must be a dictionary")
        if set(zone) != {"name", "temperature", "capacity"}:
            raise ValueError("invalid zone fields")
        name = zone["name"]
        if not isinstance(name, str):
            raise TypeError("name must be a string")
        if not name or name in names:
            raise ValueError("invalid zone name")
        names.add(name)
        temperature, capacity = _num(zone["temperature"]), _num(zone["capacity"])
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        data.append([name, temperature, capacity])
    if not isinstance(targets, dict):
        raise TypeError("targets must be a dictionary")
    if set(targets) != names:
        raise ValueError("targets must cover zones exactly")
    bounds = {}
    for name, value in targets.items():
        pair = _items(value, "target")
        if len(pair) != 2:
            raise ValueError("target must have two values")
        low, high = _num(pair[0]), _num(pair[1])
        if low > high:
            raise ValueError("invalid target range")
        bounds[name] = (low, high)
    parsed_links = []
    pairs = set()
    for link in _items(links, "links"):
        triple = _items(link, "link")
        if len(triple) != 3:
            raise ValueError("link must have three values")
        left, right, conductance = triple
        if not isinstance(left, str) or not isinstance(right, str):
            raise TypeError("link names must be strings")
        if left not in names or right not in names or left == right:
            raise ValueError("invalid link names")
        conductance = _num(conductance)
        if conductance < 0:
            raise ValueError("conductance must be non-negative")
        pair = frozenset((left, right))
        if pair in pairs:
            raise ValueError("duplicate link")
        pairs.add(pair)
        parsed_links.append((left, right, conductance))
    index = {row[0]: i for i, row in enumerate(data)}
    temperatures = [row[1] for row in data]
    for _ in range(steps):
        energy = [0.0] * len(data)
        for left, right, conductance in parsed_links:
            li, ri = index[left], index[right]
            transfer = conductance * (temperatures[ri] - temperatures[li])
            energy[li] += transfer
            energy[ri] -= transfer
        next_temperatures = [temperatures[i] + energy[i] for i in range(len(data))]
        for i, row in enumerate(data):
            low, high = bounds[row[0]]
            if next_temperatures[i] < low:
                next_temperatures[i] += 1.0
            elif next_temperatures[i] > high:
                next_temperatures[i] -= 1.0
        temperatures = next_temperatures
    return [{"name": row[0], "temperature": temperatures[i]} for i, row in enumerate(data)]

